#!/usr/bin/env node
// REAL run of the NEAR Mandate Vault on the PUBLIC NEAR TESTNET (chain_id "testnet"). Spends testnet NEAR only; mainnet is refused by every layer it goes through.
//
// WHO SIGNS WHAT (be exact when quoting this as evidence):
//   OWNER  = a DEMO owner key generated by scripts/agent-init.mjs and held on the SAME machine as the agent key (data/demo-owner.keys.json, gitignored).
//            It signs the owner-side steps through src/agent/near-admin.js. That is automation, NOT a human signature, and it does not demonstrate the owner/agent key separation
//            the real model relies on. Treat every owner-side transaction below as "demo owner (automated)".
//   AGENT  = the keystore agent key (data/agent.keys.json), through src/agent/near-signer.js with call limits (vault `draw` and `deploy` only, fee cap). Its account is the
//            64-hex implicit account of its key, first funded with 1 NEAR by the faucet-created named account that owns the same key.
// Prerequisites: data/demo-owner.keys.json and data/agent.keys.json exist; the two named accounts below exist on testnet with NEAR (created through the public testnet helper).
// Usage: NEAR_TESTNET_RUN=yes node scripts/e2e-near-testnet.mjs      (anything else exits 2 without touching the network)
// Resume after a partial run (vault already deployed, locked, allowlisted and mandated): NEAR_TESTNET_RUN=yes NEAR_RESUME=yes node scripts/e2e-near-testnet.mjs  (tops the vault up if needed, then runs steps 4-5; the evidence file is appended, not replaced)
import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadKeystore } from '../src/agent/keystore.js';
import { generateSeed, formatSecretKey, formatPublicKey, ed25519PublicKey } from '../src/agent/near-signer.js';
import { createNearAdmin, deleteKey } from '../src/agent/near-admin.js';
import { adapter, VAULT_WASM_PATH, REGISTRY_WASM_PATH, sha256Hex } from '../src/vault/near.js';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const NEAR = 10n ** 24n; const TGAS = 10n ** 12n; const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const nearStr = (y) => `${(Number(BigInt(y) / 10n ** 20n) / 1e4).toFixed(4)} NEAR`;
if (process.env.NEAR_TESTNET_RUN !== 'yes') { console.error('Refusing: this script spends public-testnet NEAR. Re-run with NEAR_TESTNET_RUN=yes.'); process.exit(2); }

const RPC = process.env.NEAR_TESTNET_RPC ?? 'https://rpc.testnet.near.org';
// The public testnet RPC rate-limits (HTTP 429). Retry those with backoff for every request this script makes (its own and the library's), never anything else.
const realFetch = globalThis.fetch;
globalThis.fetch = async (url, init) => { for (let i = 0; ; i++) { const r = await realFetch(url, init); if (r.status !== 429 || i >= 7 || !String(url).includes('rpc.testnet.near.org')) return r; await new Promise((ok) => setTimeout(ok, 1500 * 2 ** Math.min(i, 4))); } };
const OWNER = process.env.NEAR_OWNER_ACCOUNT ?? 'autonear-owner-1106.testnet';
const AGENT_NAMED = process.env.NEAR_AGENT_NAMED_ACCOUNT ?? 'autonear-agent-1106.testnet';
const TAG = process.env.NEAR_RUN_TAG ?? 'v1'; const VAULT = `vault-${TAG}.${OWNER}`; const SUBNAME = 'reg1';
const EXPLORER = 'https://testnet.nearblocks.io'; const RESUME = process.env.NEAR_RESUME === 'yes'; const EVIDENCE_OUT = resolve(ROOT, process.env.NEAR_EVIDENCE_OUT ?? `docs/testnet/near-testnet-${TAG}.json`);
const tx = (h) => `${EXPLORER}/txns/${h}`; const acct = (a) => `${EXPLORER}/address/${a}`;
const keyFile = (p) => JSON.parse(readFileSync(resolve(ROOT, p), 'utf8')).near.secretKey;
for (const p of ['data/demo-owner.keys.json', 'data/agent.keys.json']) if (!existsSync(resolve(ROOT, p))) { console.error(`missing ${p}`); process.exit(2); }
for (const p of [VAULT_WASM_PATH, REGISTRY_WASM_PATH]) if (!existsSync(p)) { console.error(`missing wasm ${p}`); process.exit(2); }

const R = { pass: 0, fail: 0, failed: [] }; const evidence = RESUME && existsSync(EVIDENCE_OUT) ? { ...JSON.parse(readFileSync(EVIDENCE_OUT, 'utf8')), resumedAt: new Date().toISOString() } : { network: 'near-testnet', chainId: 'testnet', startedAt: new Date().toISOString(), signers: { owner: `${OWNER} (DEMO owner key held on the agent's machine; automated, not a human signature)`, agent: null }, accounts: {}, txs: [], checks: [] };
const step = (n, m) => console.log(`\n[${n}] ${m}`);
function t(name, ok, detail = '') { evidence.checks.push({ name, ok: Boolean(ok), detail: String(detail).slice(0, 200) }); if (ok) { R.pass++; console.log(`   PASS  ${name}${detail ? `  (${detail})` : ''}`); } else { R.fail++; R.failed.push(name); console.log(`   FAIL  ${name}${detail ? `  (${detail})` : ''}`); } return ok; }
const rec = (label, r, who) => { if (r?.txHash) evidence.txs.push({ label, signer: who, hash: r.txHash, ok: r.ok ?? null, explorer: tx(r.txHash) }); return r; };
const rpcRaw = async (method, params) => (await (await fetch(RPC, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }) })).json());

const vaultWasm = new Uint8Array(readFileSync(VAULT_WASM_PATH)); const registryWasm = new Uint8Array(readFileSync(REGISTRY_WASM_PATH));
const vaultSha = sha256Hex(vaultWasm); const registrySha = sha256Hex(registryWasm);
const net = { id: 'near-testnet', protocol: 'near', rpc: RPC, explorer: `${EXPLORER}/txns/`, mainnet: false, networkId: 'testnet' };
console.log(`AutoNEAR Mandate Vault on the PUBLIC NEAR TESTNET. vault ${VAULT}\nvault wasm sha256 ${vaultSha}\nregistry wasm sha256 ${registrySha}`);
try {
  const status = (await rpcRaw('status', [])).result; if (status?.chain_id !== 'testnet') throw new Error(`RPC chain_id is ${status?.chain_id}, expected testnet`);
  const owner = createNearAdmin({ rpcUrl: RPC, accountId: OWNER, secretKey: keyFile('data/demo-owner.keys.json'), networkId: 'testnet' });
  const agentNamed = createNearAdmin({ rpcUrl: RPC, accountId: AGENT_NAMED, secretKey: keyFile('data/agent.keys.json'), networkId: 'testnet' });
  const keystore = loadKeystore({ path: resolve(ROOT, 'data/agent.keys.json') }); const AGENT = keystore.near.accountId; evidence.signers.agent = `${AGENT} (agent keystore key, call-limited signer)`;
  evidence.accounts = { owner: OWNER, agentNamedFunder: AGENT_NAMED, agent: AGENT, vault: VAULT, registry: `${SUBNAME}.${VAULT}` };
  const bal = async (id) => { try { return BigInt((await owner.account(id)).amount); } catch { return null; } };
  console.log(`owner ${nearStr(await bal(OWNER))}   agent-named ${nearStr(await bal(AGENT_NAMED))}   agent(implicit) ${(await bal(AGENT)) === null ? 'not on chain yet' : nearStr(await bal(AGENT))}`);

  step(1, 'agent account: fund the implicit account of the agent key (the keystore identity) from the named account that owns the same key');
  if ((await bal(AGENT)) === null) { const r = rec('agent funding (named account -> agent implicit account)', await agentNamed.transfer(AGENT, 1n * NEAR), AGENT_NAMED); t('implicit agent account created by a plain Transfer', r.ok, r.txHash); } else t('implicit agent account already exists', true);
  t('agent implicit account id = 64-hex of its ed25519 key', AGENT === Buffer.from(keystore.near.publicKey).toString('hex'));

  let vc;
  step(2, 'owner creates the vault sub-account with a throw-away key, deploys the vault wasm, then locks the account (DeleteKey)');
  if (!RESUME) {
  const kVault = (() => { const seed = generateSeed(); return { sk: formatSecretKey(seed), pk: formatPublicKey(ed25519PublicKey(seed)) }; })();
  if ((await bal(VAULT)) !== null) throw new Error(`${VAULT} already exists; set NEAR_RUN_TAG to a new value`);
  const fundYocto = BigInt(Math.round(Number(process.env.NEAR_VAULT_FUND ?? '7.6') * 1000)) * (NEAR / 1000n);
  rec('create vault sub-account + fund', await owner.createSubAccount(VAULT, kVault.pk, fundYocto), OWNER);
  const vaultAdmin = createNearAdmin({ rpcUrl: RPC, accountId: VAULT, secretKey: kVault.sk, networkId: 'testnet' });
  const init = rec('deploy vault wasm + new(owner, network_id)', await vaultAdmin.deploy(VAULT, vaultWasm, { method: 'new', args: { owner: OWNER, network_id: 'testnet' }, gas: 30n * TGAS }), VAULT);
  t('vault wasm deployed and initialised', init.ok, init.txHash);
  vc = await adapter.verifyVaultCode({ net, vault: VAULT, attested: { sha256: vaultSha } });
  t('on-chain code hash == base58(sha256(contracts/near-vault/dist/autonear_vault.wasm))', vc.ok, `sha256 ${vaultSha.slice(0, 16)}...`);
  const del = rec('DeleteKey: lock the vault account (no access keys remain)', await vaultAdmin.send(VAULT, [deleteKey(kVault.pk)]), VAULT);
  t('vault account has no access keys (code can no longer be replaced)', del.ok && (await owner.keys(VAULT)).length === 0);
  vc = await adapter.verifyVaultCode({ net, vault: VAULT, attested: { sha256: vaultSha } }); t('verifyVaultCode still ok after locking', vc.ok);
  } else { vc = await adapter.verifyVaultCode({ net, vault: VAULT, attested: { sha256: vaultSha } }); t('resume: vault on chain still has the attested code hash and no keys', vc.ok && (await owner.keys(VAULT)).length === 0); }

  step(3, 'owner allowlists the attested registry wasm with FIXED init args and grants a small, short mandate to the agent');
  const manifest = { sha256: registrySha, bytes: registryWasm.length };
  const approved = { action: 'deploy_testnet', protocol: 'near', network: 'testnet', registry: { owner: OWNER, proposer: AGENT, maxSpendCap: '0', networkId: 'testnet', contractAccount: `${SUBNAME}.${VAULT}` } };
  const exp = adapter.expectedTemplate({ manifest, payload: approved, vault: VAULT });
  if (!RESUME) rec('owner allow_template (registry id, fixed init args, deposit)', await owner.call(VAULT, 'allow_template', exp.allowTemplateArgs), OWNER);
  const blk = (await rpcRaw('block', { finality: 'final' })).result.header; const nowS = Math.floor(Number(BigInt(blk.timestamp_nanosec) / 1_000_000_000n));
  const MANDATE = { agent: AGENT, expires_at: String(nowS + 2 * 3600), per_draw_cap: String(1n * NEAR), period_secs: '3600', period_cap: String(6n * NEAR), total_cap: String(6n * NEAR), max_deploys: 1 };
  if (!RESUME) rec('owner set_mandate (agent, 2 h, per-draw 1, period 6, total 6, max 1 deploy)', await owner.call(VAULT, 'set_mandate', MANDATE), OWNER);
  let st = await adapter.readState({ net, vault: VAULT, now: nowS });
  t('readState matches what the owner set', st.config.owner === OWNER && st.mandate?.agent === AGENT && st.mandate.active && st.templates.length === 1 && st.templates[0].id === registrySha && (RESUME || (st.mandate.totalCap === MANDATE.total_cap && st.mandate.maxDeploys === 1)), `available ${nearStr(st.available)}`);
  t('checkTemplate: on-chain init_args / deposit == the approved material', adapter.checkTemplate({ state: st, expected: exp }).ok);
  console.log(`   template deposit ${nearStr(exp.deposit)}; vault available ${nearStr(st.available)}`);
  const need = BigInt(exp.deposit) + NEAR / 2n + NEAR / 5n; // one 0.5 NEAR draw + the template deposit + a little headroom for the vault's own gas
  if (BigInt(st.available) < need) {
    const topUp = need - BigInt(st.available) + NEAR / 10n; console.log(`   vault underfunded by ${nearStr(need - BigInt(st.available))}: owner tops it up with a plain transfer of ${nearStr(topUp)} (owner funding is the normal way to fund a vault)`);
    rec('owner funds the vault (plain transfer)', await owner.transfer(VAULT, topUp), OWNER); st = await adapter.readState({ net, vault: VAULT, now: nowS });
    t('vault.available() now covers one draw + one deploy', BigInt(st.available) >= need, nearStr(st.available));
  }

  step(4, 'AGENT (call-limited signer) draws gas from the vault, then deploys the attested registry THROUGH the vault');
  const limits = { maxFeePerTx: (NEAR / 10n).toString(), allowedTargets: [VAULT] };
  const signer = keystore.signer('near', adapter.signerOptions({ net, extra: { pollMs: 1500, timeoutMs: 120_000 } }));
  const settle = async (h) => { for (let i = 0; i < 40; i++) { const r = await rpcRaw('tx', { tx_hash: h, sender_account_id: AGENT, wait_until: 'FINAL' }); if (r.result) return r.result; await sleep(1500); } return null; };
  const agentRun = async (label, spec) => { const r = await signer.signAndSend(spec, limits); if (r.txHash) await settle(r.txHash); return rec(label, r, AGENT); };
  const before = BigInt((await owner.account(AGENT)).amount);
  const dr = await agentRun('agent draw 0.5 NEAR', adapter.buildCall('draw', { vault: VAULT, amount: NEAR / 2n }));
  t('agent draw accepted by the vault', dr.ok && dr.status === 'success', dr.txHash);
  t('agent balance rose by the draw minus its own gas', BigInt((await owner.account(AGENT)).amount) > before && BigInt((await owner.account(AGENT)).amount) < before + NEAR / 2n);
  const dep = await agentRun(`agent deploy ${SUBNAME} (attested registry) through the vault`, adapter.buildCall('deploy', { vault: VAULT, template: exp.templateId, code: exp.code, nameOrSalt: SUBNAME }));
  t('deploy tx: all receipts succeeded', dep.ok && dep.status === 'success', `${dep.txHash} ${dep.finality}`);
  const vd = await adapter.verifyDeploy({ net, txHash: dep.txHash, vault: VAULT, agent: AGENT, decision: { payload: JSON.stringify(approved) }, manifest, expected: { ...exp, name: SUBNAME } });
  t(`adapter.verifyDeploy ok (${vd.checks.length} independent checks incl. code hash, init args, signer, receipts)`, vd.ok && vd.account === `${SUBNAME}.${VAULT}`, vd.account);
  evidence.verifyDeploy = vd.checks.map((c) => ({ name: c.name, ok: c.ok }));
  const sub = await owner.account(`${SUBNAME}.${VAULT}`); t('deployed registry holds its storage deposit', BigInt(sub.amount) >= BigInt(exp.deposit), `${nearStr(sub.amount)}, ${sub.storage_usage} bytes`);
  console.log(`   agent paid ${nearStr(dep.tokensBurnt)} in gas for the deploy`);

  step(5, 'the leash holds on the real chain: refusals the chain itself produces');
  let r = await agentRun('NEGATIVE agent draw 2 NEAR (over per-draw cap)', { method: 'draw', target: VAULT, args: { amount: String(2n * NEAR) } });
  t('over per-draw cap: chain says E_PerDrawCap', !r.ok && /E_PerDrawCap/.test(r.failure ?? ''), String(r.failure).slice(-60));
  r = await agentRun('NEGATIVE agent second deploy (max_deploys = 1)', { method: 'deploy', target: VAULT, args: { template: registrySha, name: 'reg2', code: registryWasm } });
  t('second deploy beyond the mandate: refused by the chain', !r.ok && /E_(DeployLimit|MaxDeploys|PeriodCap|TotalCap|AddressTaken)/.test(r.failure ?? ''), String(r.failure).slice(-70));
  r = await agentRun('NEGATIVE agent deploys a wasm that is not allowlisted', { method: 'deploy', target: VAULT, args: { template: vaultSha, name: 'unlisted', code: vaultWasm } });
  t('non-allowlisted code: E_TemplateNotAllowed', !r.ok && /E_TemplateNotAllowed/.test(r.failure ?? ''));
  rec('owner revoke', await owner.call(VAULT, 'revoke', {}), OWNER);
  r = await agentRun('NEGATIVE agent draw after revoke', adapter.buildCall('draw', { vault: VAULT, amount: 1n }));
  t('after revoke: E_MandateInactive', !r.ok && /E_MandateInactive/.test(r.failure ?? ''));
  const ob = BigInt((await owner.account(OWNER)).amount);
  const wd = rec('owner withdraw 0.1 NEAR while revoked', await owner.call(VAULT, 'withdraw', { amount: String(NEAR / 10n) }), OWNER);
  t('owner can still withdraw after revoke', wd.ok && BigInt((await owner.account(OWNER)).amount) > ob + NEAR / 20n);
  st = await adapter.readState({ net, vault: VAULT, now: nowS });
  evidence.final = { usage: st.usage, available: st.available, mandateRevoked: Boolean(st.mandate?.revoked) };
} catch (e) { R.fail++; R.failed.push(`script error: ${String(e?.message ?? e).slice(0, 200)}`); console.log(`\nFAIL  script error: ${e?.stack ?? e}`); }
finally {
  evidence.finishedAt = new Date().toISOString(); evidence.result = { pass: R.pass, fail: R.fail, failed: R.failed };
  evidence.scope = 'NEAR public testnet. Owner-side transactions are signed by a DEMO owner key held on the same machine as the agent key (automation, not a human). Not an independent audit; no mainnet.';
  const out = EVIDENCE_OUT; mkdirSync(dirname(out), { recursive: true }); writeFileSync(out, `${JSON.stringify(evidence, (k, v) => (typeof v === 'bigint' ? v.toString() : v), 2)}\n`);
  console.log(`\nevidence written: ${out}`);
}
console.log(`\nRESULT: ${R.pass} PASS, ${R.fail} FAIL`); if (R.fail) console.log(`failed:\n  - ${R.failed.join('\n  - ')}`);
for (const x of evidence.txs) console.log(`  ${x.label}\n    ${x.explorer}`);
process.exit(R.fail ? 1 : 0);
